    try { const { port } = JSON.parse(await fs.readFile(ready, 'utf8')); return { child, port }; }
    catch { await new Promise(r => setTimeout(r, 100)); }
  }
  child.kill(); throw new Error('server 未就绪');
};

test('根路由返回业务首页，旧入口跳转保持可达', async t => {
  const { child, port } = await boot();
  t.after(() => child.kill());
  const base = `http://127.0.0.1:${port}`;
  const home = await fetch(base + '/');
  assert.equal(home.status, 200);
  const homeHtml = await home.text();
  assert.match(homeHtml, /实验记录/);
  assert.match(homeHtml, /新建实验/);
  for (const page of ['/home.html', '/run.html', '/settings.html']) {
    const response = await fetch(base + page);
    assert.equal(response.status, 200, page);
    assert.match(response.headers.get('content-type') || '', /text\/html/);
  }
  // 旧链接仍可达（内容为跳转页）
  for (const legacy of ['/index.html', '/connection.html', '/execution.html']) {
    const response = await fetch(base + legacy);
    assert.equal(response.status, 200, legacy);
  }
});

test('运行工作台与设置页引用的 API 真实存在', async t => {
  const { child, port } = await boot();
  t.after(() => child.kill());
  const base = `http://127.0.0.1:${port}`;
  // home.js / run.js 依赖
  const runs = await fetch(base + '/api/execution/runs');
  assert.equal(runs.status, 200);
  assert.ok(Array.isArray(await runs.json()));
  const armState = await fetch(base + '/api/execution/arm-state');
  assert.equal(armState.status, 200);
  // 指令调试 iframe 依赖的旧演示 API（app.js：/api/state、/api/command、/api/events）
  const state = await fetch(base + '/api/state');
  assert.equal(state.status, 200);
  assert.equal((await state.json()).connected, false);
});

test('设置页内嵌指令调试台（iframe embed 模式）', async () => {
  const source = await fs.readFile(path.resolve(import.meta.dirname, '../public/settings.html'), 'utf8');
  assert.match(source, /index\.html\?embed=1/);
  assert.match(source, /指令调试/);
  const index = await fs.readFile(path.resolve(import.meta.dirname, '../public/index.html'), 'utf8');
  assert.match(index, /classList\.add\('embed'\)/);
});
