[{"type":"tool_use","id":"call_1adc7e5b7ce4430ea714034c","name":"file_write","input":{"content":"/* settings.html 专属样式；基础主题沿用 connection.css。
   布局原则：这是软件不是网页——视口即窗口，页面本身不滚动；
   仅日志/字段表/表单等内部区域在空间不足时自身滚动。 */
body{grid-template-rows:50px auto minmax(0,1fr) 42px;overflow:hidden}
main{grid-template-columns:1fr;display:flex;flex-direction:column;gap:0;padding:14px 20px;overflow:hidden}
/* 三个顶层 tab 面板：均占满剩余高度，不触发页面滚动 */
#panel-conn,#panel-debug,#panel-about{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden}
#panel-conn[hidden],#panel-debug[hidden],#panel-about[hidden],.subpanel[hidden]{display:none}
/* display 覆盖不得压过 hidden 属性：隐藏的面板必须真正消失 */
.panel{display:flex;flex-direction:column;min-height:0;overflow:hidden;padding:16px 20px}
.panel .hint,.panel h2,.panel .notice{flex:none}

/* 顶层 tab 条 */
.settings-tabs{display:flex;gap:8px;padding:10px 24px 0;background:#fff;border-bottom:1px solid #d7e0e6;flex:none}
.settings-tabs button{background:transparent;border-color:transparent;padding:9px 18px;border-radius:6px 6px 0 0}
.settings-tabs button[aria-selected=true]{background:#e7f1f4;color:#0b6f7d;font-weight:650;border-color:#d7e0e6;border-bottom-color:#fff}

/* 连接与设备 · 子标签条 */
.subtabs{display:flex;gap:6px;flex:none;margin:0 0 12px;border-bottom:1px solid #dce5e9;padding-bottom:0}
.subtabs button{background:transparent;border-color:transparent;border-radius:6px 6px 0 0;padding:8px 16px;font-size:13px;color:#5b7681}
.subtabs button[aria-selected=true]{background:#e7f1f4;color:#0b6f7d;font-weight:650;border-color:transparent}
.subpanel{flex:1;min-height:0}
#sub-config .form-grid{overflow:auto;flex:1;min-height:0;padding-right:6px}
#sub-config fieldset{flex:1;min-height:0;display:flex;flex-direction:column;overflow:hidden}
.panel-foot{display:flex;gap:10px;align-items:center;flex:none;margin-top:12px;border-top:1px solid #eef3f5;padding-top:12px}

/* 报文验证：日志是唯一滚动区，其余控件固定 */
#sub-verify .actions{flex:none}
#sub-verify label{margin:8px 0}
.row-check{display:flex;align-items:center;gap:16px;flex:none;margin:6px 0}
.row-check .check{margin:0}
#log{flex:1;min-height:80px}

/* 厂商驱动：字段表内部滚动，结果区可折叠 */
.vendor-controls{display:flex;align-items:center;gap:18px;flex:none}
.vendor-controls label:first-child{margin:0}
.vendor-controls .check{margin:0;flex-direction:row}
#sub-vendor #vendor-provenance{flex:none}
.vendor-fields{max-height:none;flex:1;min-height:60px}
.vendor-results{flex:none;max-height:220px;overflow:auto}
.vendor-results pre,#sub-vendor #poll-result{flex:none;min-height:60px;max-height:160px}
#sub-vendor label{margin:8px 0}
.poll-row{display:flex;align-items:center;gap:16px;flex:none}
.poll-row h3{margin:8px 0}

/* 关于：内容短，顶部对齐即可 */
#panel-about .panel{max-width:760px;overflow:auto}
.about-list{line-height:2;color:#3d5a6c}

/* 指令调试：iframe 填满剩余空间 */
.debug-intro{flex:none}
.debug-intro h2{margin:0 0 6px}
#debug-frame{flex:1;min-height:0;border:1px solid #d7e0e6;border-radius:8px;background:#fff}

/* 共享：AI 助手抽屉 */
.ai-btn{background:transparent;border:1px solid #c7dbe0;color:#0a7f8c;border-radius:6px;padding:6px 10px;cursor:pointer;margin-left:12px}
.ai-btn:hover{background:#eef7f8}
.ai-drawer{position:fixed;top:0;right:0;bottom:0;width:320px;background:#fff;border-left:1px solid #dae3e9;box-shadow:-8px 0 24px rgba(20,40,60,.12);padding:20px;z-index:50;overflow:auto}
.ai-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.ai-drawer ul{line-height:2;color:#3d5a6c;padding-left:18px}
.ai-drawer .muted{font-size:12px}
","path":"public/settings.css"}}]

