.run-toolbar{display:flex;align-items:center;gap:16px;flex:none;flex-wrap:wrap;row-gap:8px}
.run-toolbar label{margin:0;display:flex;align-items:center;gap:10px;min-width:0}
.run-toolbar label:first-child{flex:1}
.run-toolbar select{margin:0;width:auto;max-width:100%;min-width:0}
.run-toolbar label:first-child select{flex:1}
.run-toolbar .check{font-size:12px;color:#4c666e}
.badge.armed{background:#fdeee4;color:#b36b2d}
.run-grid{display:grid;grid-template-columns:minmax(320px,1.6fr) minmax(270px,1fr);gap:12px;flex:1;min-height:0}
main{overflow:hidden}
.visual-card{display:flex;flex-direction:column;gap:8px;padding:14px}
.visual-card .section-heading h2{font-size:14px;margin:0}
.visual-card p{margin:0}
/* 3D 视图是核心资产:优先分配空间,任何情况下不被压缩至不可用 */
#run-viewport{flex:1;min-height:280px;position:relative;background:#edf4f5;border-radius:8px;overflow:hidden}
#run-viewport canvas{display:block;width:100%;height:100%}
#scene-error{position:absolute;inset:16px;color:#a3463e}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;font-size:11px;color:#647d8e;flex:none}
.metrics strong{display:block;color:#183248;font-size:15px;margin-top:4px}
.visual-card .row{flex:none}
.visual-card p.muted{flex:none;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.monitor-card{display:flex;flex-direction:column;gap:10px;padding:12px}
.monitor-card .review-tabs{flex:none}
.detail{flex:1;min-height:0}
.run-step{padding:10px;border:1px solid #dce6eb;border-radius:8px;margin-bottom:8px}
.run-step.current{border-color:#149c92;background:#eaf7f4}
.run-step.done{color:#337b67}
.run-step small{display:block;margin-top:4px}
.event{border-bottom:1px solid #e3ebef;padding:7px;font-size:12px;overflow-wrap:anywhere}
.event code{font-size:11px;color:#087c83}
#detail-resources pre{white-space:pre-wrap;font-size:12px;overflow-wrap:anywhere}
#operator-panel{background:#fff8e9;border:1px solid #e8d1a1;border-radius:8px;padding:10px}
#operator-panel h3{margin:8px 0 4px;font-size:13px}
#operator-panel p{margin:4px 0;font-size:12px}
#operator-panel label{margin:6px 0}
progress{width:100%;height:8px;accent-color:#098e94;flex:none}
#fault{width:120px;margin:0;font-size:12px}
.action-bar{flex-wrap:wrap;flex:none}
.action-bar .actions{flex-wrap:wrap}
#handoff-description{overflow-wrap:anywhere;font-size:12px}
/* 真机放行:紧凑单行,说明折叠,不挤占 3D 空间 */
.release-card{flex:none;padding:10px 16px;border-left:4px solid #0b8a6e}
.release-row{display:flex;align-items:center;gap:14px;min-width:0}
.release-row strong{white-space:nowrap;font-size:13px}
.release-row .check{margin:0;font-size:12px;white-space:nowrap}
.release-row #release-hint{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.release-detail{margin:4px 0 0;font-size:11px}
.release-detail summary{cursor:pointer}
