[{"type":"tool_use","id":"call_a060dfa5d43a45d8b39f6954","name":"file_write","input":{"content":"/**
 * Pi SDK PoC 冒烟测试(临时脚本,验证通过后删除)
 * 目标:OpenAI 兼容端点 + 自定义 DimLab 工具 + 禁用内置工具 + 事件流。
 */
import { Type } from "typebox";
import {
	createAgentSession,
	ModelRuntime,
	SessionManager,
	DefaultResourceLoader,
	getAgentDir,
} from "@earendil-works/pi-coding-agent";

const baseUrl = process.env.DIMLAB_AI_BASE_URL || "https://api.deepseek.com/v1";
const apiKey = process.env.DIMLAB_AI_KEY || "";
const modelId = process.env.DIMLAB_AI_MODEL || "deepseek-chat";

if (!apiKey) {
	console.log("SKIP: DIMLAB_AI_KEY not set");
	process.exit(0);
}

// 1. ModelRuntime:注册 OpenAI 兼容 provider
const modelRuntime = await ModelRuntime.create({ modelsPath: null });
modelRuntime.registerProvider("dimlab", {
	baseUrl,
	apiKey,
	api: "openai-completions",
	models: [
		{
			id: modelId,
			name: modelId,
			api: "openai-completions",
			reasoning: false,
			input: ["text"],
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			contextWindow: 64000,
			maxTokens: 4000,
		},
	],
});
await modelRuntime.setRuntimeApiKey("dimlab", apiKey);

const model = modelRuntime.getModel("dimlab", modelId);
console.log("model resolved:", !!model, model && `${model.provider}/${model.id}`);

// 2. 自定义工具:模拟 runs.list(返回假数据,验证模型会调用它)
const runsListTool = {
	name: "dimlab_runs_list",
	label: "DimLab Runs",
	description: "列出 DimLab 最近的实验运行记录。当用户询问运行/实验/失败情况时必须调用此工具。",
	promptSnippet: "列出最近实验运行记录",
	parameters: Type.Object({
		status: Type.Optional(Type.String({ description: "按状态过滤,如 failed/succeeded/running" })),
	}),
	execute: async (_id, params) => ({
		content: [{ type: "text", text: JSON.stringify({ runs: [{ id: "run-001", status: "failed", title: "甘油梯度稀释", error: "步骤3吸液超时", filtered_by: params.status ?? null }] }) }],
		details: {},
	}),
};

// 3. 资源加载器:纯自定义 system prompt,不加载扩展/技能/上下文文件
const loader = new DefaultResourceLoader({
	cwd: process.cwd(),
	agentDir: getAgentDir(),
	noExtensions: true,
	noSkills: true,
	noPromptTemplates: true,
	noThemes: true,
	noContextFiles: true,
	systemPrompt: "你是 DimLab 实验助手。回答关于实验运行的问题前,必须先调用 dimlab_runs_list 工具获取真实数据,不得编造。用中文简洁回答。",
});
await loader.reload();

// 4. 会话:noTools=all 禁内置,customTools 注册,内存 session
const { session } = await createAgentSession({
	modelRuntime,
	model,
	resourceLoader: loader,
	sessionManager: SessionManager.inMemory(),
	noTools: "all",
	customTools: [runsListTool],
});

try {
	session.setActiveToolsByName(["dimlab_runs_list"]);
	console.log("active tools:", session.getActiveToolNames().join(","));

	let text = "";
	const toolCalls = [];
	session.subscribe((event) => {
		if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
			text += event.assistantMessageEvent.delta;
		}
		if (event.type === "tool_execution_start") toolCalls.push(event.toolName);
	});

	await session.prompt("最近哪个实验失败了?");
	console.log("tool calls:", toolCalls.join(",") || "(none)");
	console.log("answer:", text.trim().slice(0, 300));
	console.log(text.trim() ? "POC RESULT: OK" : "POC RESULT: EMPTY");
} finally {
	session.dispose();
}
","path":"scripts/_pi-poc.mjs"}}]

