// 边界纪律：
// - noTools:"all" + 显式 allowlist：模型只能看到本包注册的只读 DimLab 工具，内置 read/bash/edit/write 全部禁用。
// - 纯自定义 system prompt：不加载扩展/技能/上下文文件，避免 pi 编码助手人格泄漏到实验台场景。
// - API key 仅驻留内存（settings.ai.api_key），不落盘、不回显；配置持久化时剔除 api_key 字段。
// - 配置变化后旧会话作废，下一条消息重建（key/base/model 与 provider 注册强绑定）。
import { ModelRuntime, SessionManager, createAgentSession, DefaultResourceLoader, getAgentDir } from '@earendil-works/pi-coding-agent';
import { dimlabTools } from './tools.mjs';

const PROVIDER_ID = 'dimlab';
const SYSTEM_PROMPT = [
  '你是 DimLab 移液工作站的操作台助手，服务对象是实验室用户，不是程序员。',
  '规则：',
  '1. 回答实验、运行、失败原因、设备错误码等事实性问题前，必须调用相应 DimLab 工具获取真实数据，禁止编造数值或状态。',
  '2. 工具返回“禁止猜测”类错误时，如实转告并建议人工核对，不要自行补全。',
  '3. 用简体中文回答，简洁直接；涉及步骤时用序号列表。',
  '4. 你不能启动、暂停、放行任何运行，也不能控制真机设备——这些操作只能在运行工作台由人完成。若用户提出此类请求，引导其前往对应页面。',
].join('\n');

export class AgentService {
  constructor({ execution, root }) {
    this.execution = execution;
    this.root = root;
    this.session = null;
    this.signature = null;
    this.busy = false;
  }

  /** 规范化配置；缺 base/key/model 时返回 null（前端据此提示去设置页）。 */
  static normalize(ai = {}) {
    const baseUrl = String(ai.base_url ?? '').trim();
    const apiKey = String(ai.api_key ?? '').trim();
    const modelId = String(ai.model ?? '').trim();
    if (!baseUrl || !apiKey || !modelId) return null;
    return { baseUrl, apiKey, modelId, contextWindow: Number(ai.context_window) || 64000, maxTokens: Number(ai.max_tokens) || 4096 };
  }

  #sig(cfg) { return `${cfg.baseUrl}\u0000${cfg.apiKey}\u0000${cfg.modelId}`; }

  async ensureSession(cfg) {
    const sig = this.#sig(cfg);
    if (this.session && this.signature === sig) return this.session;
    await this.dispose();

    const modelRuntime = await ModelRuntime.create({ modelsPath: null, refreshOnCreate: false });
    modelRuntime.registerProvider(PROVIDER_ID, {
      baseUrl: cfg.baseUrl,
      apiKey: cfg.apiKey,
      api: 'openai-completions',
      models: [{
        id: cfg.modelId, name: cfg.modelId, api: 'openai-completions', reasoning: false, input: ['text'],
        cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: cfg.contextWindow, maxTokens: cfg.maxTokens,
      }],
    });
    await modelRuntime.setRuntimeApiKey(PROVIDER_ID, cfg.apiKey);
    const model = modelRuntime.getModel(PROVIDER_ID, cfg.modelId);
    if (!model) throw new Error('AI 模型注册失败：请检查 base URL 与模型名');

    const tools = dimlabTools({ execution: this.execution, root: this.root });
    const loader = new DefaultResourceLoader({
      cwd: process.cwd(), agentDir: getAgentDir(),
      noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
      systemPrompt: SYSTEM_PROMPT,
    });
    await loader.reload();

    const { session } = await createAgentSession({
      modelRuntime, model, resourceLoader: loader,
      sessionManager: SessionManager.inMemory(),
      noTools: 'all', tools: tools.map((t) => t.name), customTools: tools,
    });
    this.session = session;
    this.signature = sig;
    return session;
  }

  /**
   * 一次对话回合。onDelta(textChunk) 收流式正文；onTool(name) 收工具执行事件。
   * 同一会话同时只允许一个回合并行推进（Pi 会话内部按轮次串行，这里再加忙闸防重入）。
   */
  async chat(cfg, message, { onDelta, onTool } = {}) {
    if (this.busy) throw Object.assign(new Error('AI 助手正忙于上一回合，请稍候'), { status: 409 });
    this.busy = true;
    try {
      const session = await this.ensureSession(cfg);
      let answer = '';
      const unsubscribe = session.subscribe((event) => {
        if (event.type === 'message_update' && event.assistantMessageEvent?.type === 'text_delta') {
          answer += event.assistantMessageEvent.delta;
          onDelta?.(event.assistantMessageEvent.delta);
        }
        if (event.type === 'tool_execution_start') onTool?.(event.toolName);
      });
      try {
        await session.prompt(message);
      } finally {
        unsubscribe?.();
      }
      return { answer: answer.trim() };
    } finally {
      this.busy = false;
    }
  }

  async dispose() {
    const session = this.session;
    this.session = null;
    this.signature = null;
    if (session) { try { session.dispose(); } catch { /* 已释放 */ } }
  }
}
