// 与 planning 的 env 级 LLM 配置（工作簿解释）相互独立；此处服务于运行台侧边栏 Agent。
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const SECRET = '\u0000stored\u0000'; // 已存过 key 的占位标记，GET 永不回显真实值

export class AiSettings {
  constructor(file = process.env.DIMLAB_AI_SETTINGS || '.dimlab/ai-settings.json') {
    this.file = resolve(file);
    this.tail = Promise.resolve();
    this.apiKey = '';
    this.hasStoredKey = false;
    this.loaded = null;
  }

  async load() {
    if (this.loaded) return this.loaded;
    let stored = { base_url: '', model: '' };
    try {
      const raw = JSON.parse(await readFile(this.file, 'utf8'));
      stored = { base_url: raw.base_url ?? '', model: raw.model ?? '', context_window: raw.context_window, max_tokens: raw.max_tokens };
      this.hasStoredKey = !!raw.api_key_stored;
      if (process.env.DIMLAB_AI_API_KEY) this.apiKey = process.env.DIMLAB_AI_API_KEY;
    } catch { /* 首次运行没有配置文件 */ }
    this.loaded = stored;
    return stored;
  }

  async publicView() {
    const s = await this.load();
    return { configured: !!(s.base_url && s.model && this.apiKey), has_key: !!this.apiKey || this.hasStoredKey, base_url: s.base_url, model: s.model, api_key: this.apiKey ? SECRET : '' };
  }

  /** 局部更新：undefined 字段保持原值；api_key 传空字符串表示清除，不传/传占位符表示保持不变。 */
  async update(patch = {}) {
    const job = this.tail.then(async () => {
      const s = await this.load();
      if (patch.base_url !== undefined) s.base_url = String(patch.base_url).trim();
      if (patch.model !== undefined) s.model = String(patch.model).trim();
      if (patch.context_window !== undefined) s.context_window = Number(patch.context_window) || undefined;
      if (patch.max_tokens !== undefined) s.max_tokens = Number(patch.max_tokens) || undefined;
      if (patch.api_key !== undefined && patch.api_key !== SECRET) {
        this.apiKey = String(patch.api_key).trim();
        this.hasStoredKey = !!this.apiKey;
      }
      if (s.base_url && !/^https?:\/\//.test(s.base_url)) Object.assign(s, { base_url: '' }, {});
      await mkdir(dirname(this.file), { recursive: true });
      // 落盘内容刻意不含密钥本体，只留“曾经配置过”的布尔痕迹。
      await writeFile(this.file, JSON.stringify({ base_url: s.base_url, model: s.model, context_window: s.context_window, max_tokens: s.max_tokens, api_key_stored: this.hasStoredKey }, null, 2));
      return this.publicView();
    });
    this.tail = job.catch(() => {});
    return job;
  }
}
