import fs from "node:fs";
import { createAgentSession, ModelRuntime, SessionManager, DefaultResourceLoader, getAgentDir } from "@earendil-works/pi-coding-agent";

const out = [];
const log = (...a) => out.push(a.map((x) => (typeof x === "string" ? x : String(x))).join(" "));
const flush = () => fs.writeFileSync("poc-result.txt", out.join("\n") + "\n", "utf8");

// 内存凭据桩：runtime 用 read() 取 key，checkAuth 因此即时通过，无需等异步 availability 刷新。
const credentialsStub = {
  async read(providerId) { return providerId === "dimlab" ? { type: "api_key", key: "mock-key" } : undefined; },
  async list() { return [{ providerId: "dimlab", type: "api_key" }]; },
  async modify(_id, fn) { return fn(undefined); },
  async delete() {},
  setRuntimeApiKey() {}, removeRuntimeApiKey() {}, hasRuntimeApiKey(p) { return p === "dimlab"; },
};

const modelRuntime = await ModelRuntime.create({ modelsPath: null, credentials: credentialsStub });
modelRuntime.registerProvider("dimlab", {
  baseUrl: "http://127.0.0.1:18091/v1",
  apiKey: "mock-key",
  api: "openai-completions",
  models: [{ id: "mock-model", name: "mock-model", api: "openai-completions", reasoning: false, input: ["text"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 64000, maxTokens: 4000 }],
});
log("hasConfiguredAuth(sync):", modelRuntime.hasConfiguredAuth("dimlab"));
await modelRuntime.refresh({ allowNetwork: false, providers: ["dimlab"] });
log("hasConfiguredAuth(after refresh):", modelRuntime.hasConfiguredAuth("dimlab"));

const runsListTool = {
  name: "dimlab_runs_list", label: "Runs", description: "列出最近实验运行记录。回答前必须调用。",
  parameters: Type.Object({ status: Type.Optional(Type.String()) }),
  execute: async () => ({ content: [{ type: "text", text: JSON.stringify({ runs: [{ id: "run-001", status: "failed", title: "甘油梯度稀释" }] }) }], details: {} }),
};

const loader = new DefaultResourceLoader({
  cwd: process.cwd(), agentDir: getAgentDir(),
  noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
  systemPrompt: "你是 DimLab 实验助手。必须先调用 dimlab_runs_list 获取数据再回答，不得编造。用中文简洁回答。",
});
await loader.reload();

const { session } = await createAgentSession({
  modelRuntime, model: modelRuntime.getModel("dimlab", "mock-model"), resourceLoader: loader,
  sessionManager: SessionManager.inMemory(), noTools: "all", tools: ["dimlab_runs_list"], customTools: [runsListTool],
});
try {
  log("active:", session.getActiveToolNames().join(","));
  let text = ""; const toolCalls = []; const errs = [];
  session.subscribe((event) => {
    if (event.type === "message_update" && event.assistantMessageEvent?.type === "text_delta") text += event.assistantMessageEvent.delta;
    if (event.type === "tool_execution_start") toolCalls.push(event.toolName);
    if (event.type === "auto_retry_start") errs.push(event.errorMessage);
  });
  await session.prompt("最近哪个实验失败了？");
  log("tool calls:", toolCalls.join(",") || "(none)");
  log("answer:", text.trim().slice(0, 300));
  if (errs.length) log("retry errors:", [...new Set(errs)].join("; "));
  log(text.trim() ? "POC RESULT: OK" : "POC RESULT: EMPTY");
} finally {
  flush();
  session.dispose();
}
","path":"scripts/_pi-poc.mjs"}}]

