const settings = await (await fetch(`${base}/api/ai/settings`, { headers: { Origin: base } })).json();
console.log("settings:", JSON.stringify(settings));

const res = await fetch(`${base}/api/ai/chat`, {
  method: "POST",
  headers: { Origin: base, "Content-Type": "application/json" },
  body: JSON.stringify({ message: "最近哪些实验失败了？" }),
});
console.log("chat status:", res.status);
const reader = res.body.getReader(), decoder = new TextDecoder();
let buf = "", deltas = "", tools = [], errors = [];
while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buf += decoder.decode(value, { stream: true });
  const parts = buf.split("\n\n"); buf = parts.pop() || "";
  for (const part of parts) {
    const line = part.split("\n").find((l) => l.startsWith("data: "));
    if (!line) continue;
    let d; try { d = JSON.parse(line.slice(6)); } catch { continue; }
    if (d.event === "delta") deltas += d.text;
    if (d.event === "tool") tools.push(d.name);
    if (d.event === "error") errors.push(d.message);
    if (d.event === "done") console.log("done.text len:", (d.text || "").length);
  }
}
console.log("tools:", tools.join(",") || "(none)");
console.log("deltas:", deltas.trim().slice(0, 200) || "(empty)");
if (errors.length) console.log("errors:", errors.join("; "));
