+// Read-only status poll (0x0100) with the same gate + seq + unknown discipline as vendorSend.
+export async function vendorPoll(link, { confirmed }, sendRaw) {
+  if (confirmed !== true) throw new Error('厂商驱动发送必须显式确认（confirmed=true）');
+  const seq = ++link.seq;
