// —— 受确认闸门管控的写操作工具：模型只能起草，人点「确认执行」才落地 ——
const makeGatedEngine = () => ({
  summary: () => [{ id: 'run-9', status: 'queued', created_at: '2026-10-25T12:00:00Z', title: 'DNA稀释', plan_hash: 'h9', step_index: 0, compilation_id: 'c9' }],
  view: (id) => ({ id, status: 'queued' }),
  submits: [], controls: [],
  async submit(p) { this.submits.push(p); return { id: 'run-new', status: 'queued', ...p }; },
  async control(id, c) { this.controls.push([id, c]); return { id, status: 'running', action: c.action }; },
});
const gateState = { armed: false, bridgeUrl: '', endpoint: null };
const gated = gatedTools({ execution: makeGatedEngine(), gateState });
const gcall = async (name, params) => JSON.parse((await gated.find((t) => t.name === name).execute('t', params)).content[0].text);

test('dimlab_run_start 未确认时只返回草案，绝不提交', async () => {
  const out = await gcall('dimlab_run_start', { run_id: 'run-9' });
  assert.equal(out.status, 'draft');
  assert.equal(out.requires_confirmation, true);
  assert.deepEqual(JSON.parse(out.confirmation_payload), { compilation_id: 'c9', idempotency_key: out.proposal.idempotency_key, execution_mode: 'simulation' });
  assert.equal(out.proposal.speed, 10);
  assert.ok(/^[A-Za-z0-9_-]{8,100}$/.test(out.proposal.idempotency_key));
  assert.equal(gated.find((t) => t.name === 'dimlab_run_start').execution.submits.length, 0);
});

test('dimlab_run_start confirmed=true 走引擎提交并复用幂等键', async () => {
  const draft = await gcall('dimlab_run_start', { run_id: 'run-9' });
  const key = JSON.parse(draft.confirmation_payload).idempotency_key;
  const done = await gcall('dimlab_run_start', { run_id: 'run-9', confirmed: true, idempotency_key: key });
  assert.equal(done.status, 'submitted');
  assert.equal(done.run.id, 'run-new');
  const engine = gated.find((t) => t.name === 'dimlab_run_start').execution;
  assert.equal(engine.submits.length, 1);
  const again = await gcall('dimlab_run_start', { run_id: 'run-9', confirmed: true, idempotency_key: key });
  assert.equal(again.reused, true);
  assert.equal(engine.submits.length, 1, '确认后重复调用不得二次提交');
});

test('dimlab_run_control 合法动作直接执行；非法动作拒绝', async () => {
  const paused = await gcall('dimlab_run_control', { run_id: 'run-9', action: 'pause' });
  assert.equal(paused.status, 'done');
  assert.equal(paused.action, 'pause');
  const bad = await gcall('dimlab_run_control', { run_id: 'run-9', action: 'reboot' });
  assert.match(bad.error, /允许：/);
});

