/**
 * 受确认闸门管控的写操作工具。仅当调用方（服务端代执行或前端确认流）显式传 confirmed=true
 * 才会落地；真机武装（arm）不在模型可见工具集内，只能经 gateState.arm() 由服务端在用户确认后调用。
 * @param {object} deps
 * @param {object} deps.execution 执行引擎（submit/control/view/summary）
 * @param {object} deps.gateState 服务端闸门：{ armed, bridgeUrl, endpoint, arm? }
 */
export function gatedTools({ execution, gateState = {} }) {
  const started = new Map(); // idempotency_key -> run view，防确认后重复提交
  return [
    {
      name: 'dimlab_run_start',
      label: '启动仿真运行',
      description: '为某条已有编译记录（compilation_id）起草一次仿真运行。未确认时只返回草案与幂等键，不会启动；必须征得用户明确同意后再次调用并传 confirmed=true + 同一 idempotency_key。', 
      promptSnippet: '按编译记录启动仿真运行',
      parameters: Type.Object({
        run_id: Type.Optional(Type.String({ description: '已有运行 id（从其 compilation_id 重新发起）' })),
        compilation_id: Type.Optional(Type.String({ description: '直接指定编译记录 id（与 run_id 二选一）' })),
        speed: Type.Optional(Type.Number({ description: '虚拟时钟倍率，默认 10' })),
        confirmed: Type.Optional(Type.Boolean({ description: '用户已明确同意启动此仿真运行' })),
        idempotency_key: Type.Optional(Type.String({ description: '草案阶段返回的幂等键，确认时必须原样带回' })),
      }),
      execute: async (_id, params) => {
        let compilationId = params.compilation_id;
        if (!compilationId && params.run_id) compilationId = execution.summary().find((r) => r.id === params.run_id)?.compilation_id;
        if (!compilationId) return text({ error: '缺少 compilation_id 或可溯源的 run_id，请先用 dimlab_runs_list 查证' });
        const key = params.idempotency_key || randomUUID();
        const speed = [1, 4, 10, 20, 100].includes(params.speed) ? params.speed : 10;
        const payload = { compilation_id: compilationId, idempotency_key: key, speed, execution_mode: 'simulation' };
        if (params.confirmed !== true) {
          return text({ status: 'draft', requires_confirmation: true, note: '尚未启动。请向用户展示以下参数并征得同意，确认后携带 confirmed=true 与同一 idempotency_key 重试。', proposal: { compilation_id: compilationId, idempotency_key: key, speed, execution_mode: 'simulation' }, confirmation_payload: JSON.stringify(payload) });
        }
        if (started.has(key)) return text({ status: 'submitted', reused: true, run: started.get(key) });
        try {
          const run = await execution.submit(payload);
          started.set(key, run);
          return text({ status: 'submitted', run });
        } catch (error) {
          return text({ error: `启动失败：${error.message ?? error}` });
        }
      },
    },
    {
      name: 'dimlab_run_control',
      label: '运行控制',
      description: '对一次进行中的运行执行 pause / resume / cancel。这些改变实验进程的动作必须先向用户复述影响并获得明确同意，再传 confirmed=true。',
      promptSnippet: '暂停/继续/取消运行',
      parameters: Type.Object({
        run_id: Type.String({ description: '运行 id' }),
        action: Type.String({ description: 'pause | resume | cancel' }),
        confirmed: Type.Optional(Type.Boolean({ description: '用户已明确同意该操作' })),
      }),
      execute: async (_id, params) => {
        if (!['pause', 'resume', 'cancel'].includes(params.action)) return text({ error: `不允许的动作：${params.action}（允许：pause/resume/cancel）` });
        if (params.confirmed !== true) {
          return text({ status: 'needs_confirmation', requires_confirmation: true, note: `未执行。${params.action === 'cancel' ? '取消会终止运行且保留已发生的物料变化，不可自动回滚' : `将${params.action === 'pause' ? '暂停' : '恢复'}运行 ${params.run_id}`}。请先征得用户同意，再以 confirmed=true 重试。`, confirmation_payload: JSON.stringify({ run_id: params.run_id, action: params.action, confirmed: true }) });
        }
        try {
          const result = await execution.control(params.run_id, { action: params.action, request_id: randomUUID() });
          return text({ status: 'done', run_id: params.run_id, action: params.action, result });
        } catch (error) {
          return text({ error: `控制失败：${error.message ?? error}` });
        }
      },
    },
    {
      name: 'dimlab_arm_request',
      label: '真机武装说明',
      description: '回答用户关于“能否上真机/如何放行硬件执行”的问题：检查当前武装状态与桌面桥连接情况，给出下一步指引。本工具不能武装设备——必须由用户在运行工作台勾选确认后由界面完成。',
      promptSnippet: '检查真机放行条件',
      parameters: Type.Object({}),
      execute: async () => {
        return text({
          armed: !!gateState.armed,
          bridge_connected: !!gateState.bridgeUrl,
          endpoint: gateState.endpoint ?? null,
          note: gateState.armed ? '真机执行已武装，可在运行工作台提交 hardware 模式运行。' : '未武装。放行路径：运行工作台 → 真机放行面板 → 勾选「我确认设备已就绪」→ 确认（需桌面桥在线且通道已连接）。AI 无权武装设备。',
        });
      },
    },
  ];
}

