import { createServer } from 'node:http';

const server = createServer((req, res) => {
  let body = '';
  req.on('data', (c) => body += c);
  req.on('end', () => {
    const payload = JSON.parse(body || '{}');
    const messages = payload.messages ?? [];
    const last = messages[messages.length - 1] ?? {};
    const toolCalled = messages.some((m) => m.role === 'tool');
    const sse = (obj) => res.write(`data: ${JSON.stringify(obj)}\n\n`);
    res.writeHead(200, { 'Content-Type': 'text/event-stream' });
    if (!toolCalled && last.role === 'user') {
      // 第一轮：调用启动仿真工具（不带 confirmed → 应只得到草案）
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: { tool_calls: [{ index: 0, id: 'call1', function: { name: 'dimlab_run_start', arguments: '{}' } }] }, finish_reason: null }] });
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: {}, finish_reason: 'stop' }] });
    } else if (!messages.some((m) => m.content === 'CONFIRM_ROUND')) {
      // 第二轮：告知用户需要确认
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: { content: '已起草启动方案，请确认后执行。' }, finish_reason: null }] });
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: {}, finish_reason: 'stop' }] });
    } else {
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: { content: '好的。' }, finish_reason: null }] });
      sse({ id: 'c', object: 'chat.completion.chunk', choices: [{ delta: {}, finish_reason: 'stop' }] });
    }
    res.end();
  });
});
server.listen(3457, '127.0.0.1', () => console.log('MOCK-READY'));
","path":"scripts/_e2e-confirm.mjs"}}]

[{"type":"tool_use","id":"call_db2531ff4fb94b3e801d7f8e","name":"file_write","input":{"content":"// 临时驱动：AgentService + gatedTools 全链路（草案 → 服务端代执行确认）。
import { AgentService } from '../packages/agent-tools/agent.mjs';

const fakeExecution = {
  submits: [], controls: [],
  summary: () => [{ id: 'run-x', status: 'queued', compilation_id: 'c-abc', title: 'DNA稀释' }],
  view: (id) => ({ id, status: 'queued' }),
  async submit(p) { this.submits.push(p); return { id: 'run-new', status: 'queued', compilation_id: p.compilation_id }; },
  async control(id, c) { this.controls.push([id, c.action]); return { id, status: 'paused' }; },
};
const svc = new AgentService({ execution: fakeExecution, root: new URL('../../', import.meta.url) });
const cfg = { baseUrl: 'http://127.0.0.1:3457/v1', apiKey: 'test', modelId: 'mock-model', contextWindow: 8000, maxTokens: 512 };

const { answer } = await svc.chat(cfg, '帮我启动 run-x 的仿真', {});
console.log('ANSWER:', answer);
const pending = svc.listPendingConfirmations();
console.log('PENDING:', JSON.stringify(pending.map((p) => p.tool_name)));
if (!pending.length) { console.error('E2E RESULT: FAIL (no confirmation captured)'); process.exit(1); }
const out = await svc.executeConfirmation(cfg, pending[0].token);
console.log('CONFIRM:', JSON.stringify(out));
console.log('SUBMITS:', fakeExecution.submits.length);
if (out.ok && fakeExecution.submits.length === 1) {
  const again = await svc.executeConfirmation(cfg, pending[0].token).catch((e) => ({ err: e.message }));
  console.log('REPLAY:', JSON.stringify(again));
  console.log('E2E RESULT: OK');
} else {
  console.error('E2E RESULT: FAIL');
}
await svc.dispose();
process.exit(0);
","path":"scripts/_e2e-drive.mjs"}}]

