[{"type":"tool_use","id":"call_0e1ff9d0b11d4280a28139c2","name":"file_write","input":{"content":"// S3 多设备并行调度器：就绪集 = depends_on 全部完成 且 该步骤设备空闲。
// 纯函数、无副作用；engine.tick 消费本模块结果，检查点里 run.actions/run.completed 由引擎维护。
export function deviceOf(plan, stepId) {
  const binding = plan.bindings.find(b => b.step_id === stepId);
  return binding?.executor === 'device' ? binding.device_id : null;
}

/**
 * @param run 需含 {status:'running', plan:{experiment:{steps},bindings}, actions:Map<device_id,action>, completed:Set<step_id>}
 * @returns 可同一 tick 启动/推进的步骤（每设备至多一个；manual 步骤不占设备）
 */
export function readySteps(run) {
  if (run.status !== 'running') return [];
  const steps = run.plan.experiment.steps;
  const busy = new Set([...run.actions.keys()]);
  const out = [], seen = new Set();
  for (const step of steps) {
    if (seen.has(step.step_id)) continue; // 同一步骤只取一次（重复 id 已由合同层拒绝）
    if (run.completed.has(step.step_id)) continue;
    if (busy.has(step.step_id)) continue;
    if (!step.depends_on.every(d => run.completed.has(d))) continue;
    const dev = deviceOf(run.plan, step.step_id);
    if (dev && busy.has(dev)) continue;
    out.push(step);
    if (dev) busy.add(dev);
    seen.add(step.step_id);
  }
  return out;
}

/**
 * 旧版检查点迁移：run.action（单动作游标）→ run.actions:{[device_id]:action}。
 * 就地修改并返回同一对象（幂等：已是新结构则原样返回）。
 */
export function migrateRun(run) {
  if (!run.actions || run.actions instanceof Map) return run;
  if (!(run.actions instanceof Map)) {
    const next = new Map(Object.entries(run.actions ?? {}));
    run.actions = next;
  }
  if (run.action && !run._migrated_action_done) {
    const step = run.plan?.experiment?.steps?.[run.step_index];
    const dev = step ? deviceOf(run.plan, step.step_id) : null;
    if (dev) run.actions.set(dev, run.action);
    run._migrated_action_done = true;
    run.action = null;
  } else if (run.action === null || run.action === undefined) {
    run.action = null;
  }
  if (!run.completed) run.completed = new Set();
  return run;
}
