   demand(!terminal.has(run.status),'TERMINAL','运行已结束',409);
   if(action==='pause'){demand(['running','waiting_for_operator'].includes(run.status),'STATE','当前状态不能暂停',409);run.resume_status=run.status;run.status='paused';}
